from pathlib import Path

engine=Path('backend/engine.mjs')
s=engine.read_text(encoding='utf-8')
if "infrastructure:{clientId:'client_id'" not in s:
    s=s.replace(" appointments:{clientId:'client_id',title:'title',date:'date',time:'start_time',duration:'duration_minutes',status:'status',location:'location',notes:'notes'}", " appointments:{clientId:'client_id',title:'title',date:'date',time:'start_time',duration:'duration_minutes',status:'status',location:'location',notes:'notes'},\n infrastructure:{clientId:'client_id',category:'category',provider:'provider',accountEmail:'account_email',accountName:'account_name',username:'username',projectName:'project_name',projectUrl:'project_url',notes:'notes',active:'active'}")
    s=s.replace("const allowed=columns[a.entity],old=a.operation==='update'?next[a.entity].find(x=>x.id===a.id):null;", "const allowed=columns[a.entity],old=a.operation==='update'?next[a.entity].find(x=>String(x.id)===String(a.id)):null;")
    s=s.replace("else if(key==='duration'){if(!Number.isInteger(value)||value<5||value>1440)throw Error('Duração inválida.');fields[key]=value}\n   else {", "else if(key==='duration'){if(!Number.isInteger(value)||value<5||value>1440)throw Error('Duração inválida.');fields[key]=value}\n   else if(key==='active'){if(typeof value!=='boolean')throw Error('Status de infraestrutura inválido.');fields[key]=value}\n   else {")
    s=s.replace("if(fields.url){const u=new URL(fields.url);if(!['https:','http:'].includes(u.protocol))throw Error('Link inválido.')}", "if(fields.url){const u=new URL(fields.url);if(!['https:','http:'].includes(u.protocol))throw Error('Link inválido.')}\n  if(fields.projectUrl){const u=new URL(fields.projectUrl);if(!['https:','http:'].includes(u.protocol))throw Error('Link inválido.')}")
    s=s.replace("const defaults=Object.fromEntries(Object.keys(allowed).map(k=>[k,k==='value'?0:k==='duration'?60:'']));\n  defaults.status=statuses[a.entity][0];", "const defaults=Object.fromEntries(Object.keys(allowed).map(k=>[k,k==='value'?0:k==='duration'?60:k==='active'?true:'']));\n  if(statuses[a.entity])defaults.status=statuses[a.entity][0];")
    s=s.replace("const record={...(old||defaults),...fields,id:old?.id||randomUUID()};\n  if(!(record.name||record.title||'').trim())throw Error('Informe o nome ou título.');", "const record={...(old||defaults),...fields,id:old?.id||(a.entity==='infrastructure'?'new':randomUUID())};\n  if(a.entity!=='infrastructure'&&!(record.name||record.title||'').trim())throw Error('Informe o nome ou título.');\n  if(a.entity==='infrastructure'&&(!record.clientId||!record.category||!record.provider))throw Error('Informe cliente, categoria e provedor da infraestrutura.');")
    s=s.replace("if(old)Object.assign(old,record);else next[a.entity].push(record);", "if(old)Object.assign(old,record);else next[a.entity].push(record);")
    s=s.replace("if(change.operation==='update')return {text:'UPDATE public.'+change.entity+' SET '+cols.map((c,i)=>c+'=$'+(i+1)).join(',')+',updated_at=now() WHERE id=$'+(values.length+1)+' AND deleted_at IS NULL',values:[...values,change.id]};\n return {text:'INSERT INTO public.'+change.entity+' (id,'+cols.join(',')+') VALUES ('+[change.id,...values].map((_,i)=>'$'+(i+1)).join(',')+')',values:[change.id,...values]};", "const table=change.entity==='infrastructure'?'client_infrastructure':change.entity;\n if(change.operation==='update'){const deleted=change.entity==='infrastructure'?'':' AND deleted_at IS NULL';return {text:'UPDATE public.'+table+' SET '+cols.map((c,i)=>c+'=$'+(i+1)).join(',')+',updated_at=now() WHERE id=$'+(values.length+1)+deleted,values:[...values,change.id]}}\n if(change.entity==='infrastructure')return {text:'INSERT INTO public.client_infrastructure ('+cols.join(',')+') VALUES ('+values.map((_,i)=>'$'+(i+1)).join(',')+')',values};\n return {text:'INSERT INTO public.'+table+' (id,'+cols.join(',')+') VALUES ('+[change.id,...values].map((_,i)=>'$'+(i+1)).join(',')+')',values:[change.id,...values]};")
    engine.write_text(s,encoding='utf-8')

index=Path('backend/index.mjs')
s=index.read_text(encoding='utf-8')
if 'async function infrastructure(db)' not in s:
    anchor="async function appointments(db){return (await db.query(\"SELECT id,COALESCE(client_id,'') AS \\\"clientId\\\",title,date::text AS date,to_char(start_time,'HH24:MI') AS time,duration_minutes AS duration,status,location,notes,created_at AS \\\"createdAt\\\",updated_at AS \\\"updatedAt\\\" FROM public.appointments WHERE deleted_at IS NULL ORDER BY date,start_time,created_at\")).rows}"
    infra="async function infrastructure(db){return (await db.query(\"SELECT id,client_id AS \\\"clientId\\\",category,provider,COALESCE(account_email,'') AS \\\"accountEmail\\\",COALESCE(account_name,'') AS \\\"accountName\\\",COALESCE(username,'') AS username,COALESCE(project_name,'') AS \\\"projectName\\\",COALESCE(project_url,'') AS \\\"projectUrl\\\",COALESCE(notes,'') AS notes,active,created_at AS \\\"createdAt\\\",updated_at AS \\\"updatedAt\\\" FROM public.client_infrastructure ORDER BY client_id,category,provider,id\")).rows}"
    if anchor not in s: raise SystemExit('appointments anchor not found')
    s=s.replace(anchor,anchor+'\n'+infra,1)
    s=s.replace("state.appointments=await appointments(db);return state", "state.appointments=await appointments(db);state.infrastructure=await infrastructure(db);return state",1)
    s=s.replace("appointments:state.appointments};", "appointments:state.appointments,infrastructure:state.infrastructure};",1)
    s=s.replace("Não transfira registros. Acesso a arquivos", "Para infrastructure, clientId, category e provider são obrigatórios; use accountEmail, accountName, username, projectName, projectUrl, notes e active quando informados. Infrastructure representa Vercel/hospedagem, GitHub, banco Neon/Supabase, armazenamento R2, IA/API, domínio, e-mail e outros serviços. Nunca coloque senhas, tokens, API keys ou chaves privadas em infrastructure. Não transfira registros. Acesso a arquivos",1)
    s=s.replace("public.finances,public.appointments IN SHARE ROW EXCLUSIVE MODE", "public.finances,public.appointments,public.client_infrastructure IN SHARE ROW EXCLUSIVE MODE",1)
    index.write_text(s,encoding='utf-8')

print('Assistente IA habilitado para client_infrastructure.')
